window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["slack"]={html:"<div class=\"own-slack\">\n  <!-- ── NAV ─────────────────────────────────────────────────────────── -->\n  <header class=\"sl-nav\">\n    <a class=\"sl-brand\" href=\"#sl-top\"><span class=\"sl-brand-mark\" aria-hidden=\"true\"></span>Northwind</a>\n    <nav class=\"sl-nav-links\" aria-label=\"Primary\">\n      <a href=\"#sl-features\">Features</a>\n      <a href=\"#sl-channels\">Channels</a>\n      <a href=\"#sl-pricing\">Pricing</a>\n      <a href=\"#sl-stats\">Results</a>\n    </nav>\n    <div class=\"sl-nav-right\">\n      <a class=\"sl-pill sl-pill-soft\" href=\"#\">Sign in</a>\n      <a class=\"sl-pill sl-pill-primary\" href=\"#sl-pricing\">Try for free</a>\n    </div>\n  </header>\n\n  <main id=\"sl-top\">\n    <!-- ── HERO (pastel-mesh) ─────────────────────────────────────────── -->\n    <section class=\"sl-hero\" aria-labelledby=\"sl-h1\">\n      <div class=\"sl-hero-copy\">\n        <h1 id=\"sl-h1\" class=\"sl-display\">Operations, aligned<br>in one channel.</h1>\n        <p class=\"sl-hero-sub\">Northwind brings your dashboards, regional teams, and alerts into a single place to work — so nothing gets lost between shifts.</p>\n        <div class=\"sl-hero-cta\">\n          <a class=\"sl-pill sl-pill-primary\" href=\"#sl-pricing\">Get started</a>\n          <a class=\"sl-pill sl-pill-outline\" href=\"#\">Request a demo</a>\n        </div>\n        <p class=\"sl-hero-note\">Free for small teams. <a class=\"sl-link\" href=\"#sl-pricing\">See pricing</a></p>\n      </div>\n      <div class=\"sl-mockup\" aria-label=\"Northwind workspace preview\">\n        <div class=\"sl-mk-side\">\n          <span class=\"sl-mk-ws\">Northwind Ops</span>\n          <ul class=\"sl-mk-channels\">\n            <li class=\"on\"># throughput</li>\n            <li># region-luzon</li>\n            <li># region-visayas</li>\n            <li># alerts</li>\n            <li># forecast</li>\n          </ul>\n        </div>\n        <div class=\"sl-mk-main\">\n          <div class=\"sl-mk-head\"># throughput <span class=\"sl-mk-sub\">3 members · 12 charts</span></div>\n          <div class=\"sl-msg\">\n            <span class=\"sl-av\">RS</span>\n            <div><b>Rhea Santos</b> <span class=\"sl-time\">09:12</span><p>Luzon came in at <b>3,987/hr</b> — 5% under target. Chart posted.</p></div>\n          </div>\n          <div class=\"sl-msg\">\n            <span class=\"sl-av sl-av-2\">DO</span>\n            <div><b>Dane Ocampo</b> <span class=\"sl-time\">09:14</span><p>Visayas is up 6.9%. I'll roll the region view now.</p></div>\n          </div>\n          <div class=\"sl-chart-card\">\n            <div class=\"sl-cc-bars\"><span style=\"--h:54%\"></span><span style=\"--h:78%\"></span><span style=\"--h:46%\"></span><span style=\"--h:90%\"></span><span style=\"--h:66%\"></span><span style=\"--h:82%\"></span></div>\n            <span class=\"sl-cc-label\">throughput · last 7 days</span>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── LOGO STRIP ─────────────────────────────────────────────────── -->\n    <section class=\"sl-logos\" aria-label=\"Trusted by\">\n      <span>ATLAS</span><span>KESTREL</span><span>MERIDIAN</span><span>HELIOS</span><span>NORTHFORK</span><span>BLUEPRINT</span>\n    </section>\n\n    <!-- ── FEATURES (cream cards) ─────────────────────────────────────── -->\n    <section id=\"sl-features\" class=\"sl-band\">\n      <p class=\"sl-eyebrow\">What teams get</p>\n      <h2 class=\"sl-display-md\">Everything the floor needs,<br>nothing it doesn't.</h2>\n      <div class=\"sl-grid\" id=\"slFeatureGrid\"></div>\n    </section>\n\n    <!-- ── CHANNELS SPLIT ─────────────────────────────────────────────── -->\n    <section id=\"sl-channels\" class=\"sl-split\">\n      <div class=\"sl-split-copy\">\n        <p class=\"sl-eyebrow\">Organise by region</p>\n        <h2 class=\"sl-display-md\">A channel for<br>every site.</h2>\n        <p class=\"sl-body\">Spin up a channel per region and Northwind threads the right dashboards, alerts, and people into it automatically. <a class=\"sl-link\" href=\"#\">How channels work</a></p>\n      </div>\n      <div class=\"sl-channel-list\" id=\"slChannelList\"></div>\n    </section>\n\n    <!-- ── STATS ──────────────────────────────────────────────────────── -->\n    <section id=\"sl-stats\" class=\"sl-stats\" aria-label=\"Results\">\n      <div class=\"sl-stat\"><b>90%</b><span>faster incident handoffs</span></div>\n      <div class=\"sl-stat\"><b>43</b><span>regions on one platform</span></div>\n      <div class=\"sl-stat\"><b>87%</b><span>fewer status meetings</span></div>\n    </section>\n\n    <!-- ── PRICING ────────────────────────────────────────────────────── -->\n    <section id=\"sl-pricing\" class=\"sl-band\">\n      <p class=\"sl-eyebrow\">Pricing</p>\n      <h2 class=\"sl-display-md\">Simple plans for<br>operations teams.</h2>\n      <div class=\"sl-tiers\" id=\"slTierGrid\"></div>\n    </section>\n\n    <!-- ── AUBERGINE CTA BAND ─────────────────────────────────────────── -->\n    <section class=\"sl-cta-band\" aria-labelledby=\"sl-cta-h\">\n      <div class=\"sl-cta-copy\">\n        <h2 id=\"sl-cta-h\" class=\"sl-display-md sl-on-ink\">Ready to align<br>your operations?</h2>\n        <p class=\"sl-body sl-on-ink-mute\">Bring every region onto one floor. Free for small teams, no card required.</p>\n      </div>\n      <div class=\"sl-cta-actions\">\n        <a class=\"sl-pill sl-pill-light\" href=\"#\">Try for free</a>\n        <a class=\"sl-pill sl-pill-outline-light\" href=\"#\">Talk to sales</a>\n      </div>\n    </section>\n  </main>\n\n  <!-- ── FOOTER (aubergine) ─────────────────────────────────────────── -->\n  <footer class=\"sl-footer\">\n    <div class=\"sl-foot-grid\">\n      <div class=\"sl-foot-brand\">\n        <span class=\"sl-brand sl-on-ink\"><span class=\"sl-brand-mark\" aria-hidden=\"true\"></span>Northwind</span>\n        <p class=\"sl-body sl-on-ink-mute\">Operations analytics for teams that run the floor together.</p>\n      </div>\n      <div class=\"sl-foot-col\"><h3>Product</h3><a href=\"#\">Channels</a><a href=\"#\">Dashboards</a><a href=\"#\">Alerts</a></div>\n      <div class=\"sl-foot-col\"><h3>Developers</h3><a href=\"#\">API</a><a href=\"#\">Docs</a><a href=\"#\">Status</a></div>\n      <div class=\"sl-foot-col\"><h3>Company</h3><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Contact</a></div>\n    </div>\n    <div class=\"sl-foot-row\"><span>Sample data — showcase only</span><span>© 2026 Northwind</span></div>\n  </footer>\n</div>\n",css:"/* ══ SLACK — own layout for showcase.html ════════════════════════════════\n   Aubergine primary with cream-lavender pastel-mesh hero, floating product UI\n   mockups, blue inline links, over-padded 90px pill buttons, and huge aubergine\n   display statistics. Inter substitutes the two proprietary humanist faces.\n   Scoped under `.own-slack`. */\n\n.own-slack {\n  --primary: #4a154b;\n  --primary-press: #611f69;\n  --ink: #1d1d1d;\n  --ink-mute: #696969;\n  --link-blue: #1264a3;\n  --link-hover: #3860be;\n  --canvas: #ffffff;\n  --canvas-cream: #f4ede4;\n  --canvas-lavender: #f9f0ff;\n  --surface-aubergine: #4a154b;\n  --hairline: #e6e6e6;\n  --on-aubergine-mute: #d9bdde;\n\n  --f-display: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, sans-serif;\n  --f-ui: 'Inter', system-ui, -apple-system, sans-serif;\n\n  --gut: clamp(20px, 4.4cqi, 56px);\n  --sec: clamp(56px, 9cqi, 96px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--f-ui);\n  font-size: 16px;\n  line-height: 1.55;\n  text-align: left;\n  overflow-x: clip;\n  -webkit-font-smoothing: antialiased;\n}\n.own-slack *, .own-slack *::before, .own-slack *::after { box-sizing: border-box; }\n.own-slack :focus-visible { outline: 3px solid var(--link-hover); outline-offset: 3px; border-radius: 8px; }\n.own-slack .sl-on-ink { color: #fff; }\n.own-slack .sl-on-ink-mute { color: var(--on-aubergine-mute); }\n\n/* ── type ────────────────────────────────────────────────────────────── */\n.own-slack .sl-display {\n  font-family: var(--f-display); font-weight: 700;\n  font-size: clamp(38px, 6.4cqi, 64px); line-height: 1.12; letter-spacing: -0.012em; margin: 0;\n}\n.own-slack .sl-display-md {\n  font-family: var(--f-display); font-weight: 700;\n  font-size: clamp(28px, 3.6cqi, 50px); line-height: 1.14; letter-spacing: -0.008em; margin: 0 0 22px;\n}\n.own-slack .sl-eyebrow { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.96px; color: var(--ink-mute); margin: 0 0 18px; }\n.own-slack .sl-body { font-size: 18px; font-weight: 400; line-height: 1.55; color: var(--ink-mute); max-width: 58ch; }\n.own-slack .sl-hero-sub { margin: 22px 0 30px; font-size: 18px; line-height: 1.55; color: var(--ink-mute); max-width: 48ch; }\n.own-slack .sl-link { color: var(--link-blue); text-decoration: none; }\n.own-slack .sl-link:hover { color: var(--link-hover); text-decoration: underline; }\n\n/* ── pills ───────────────────────────────────────────────────────────── */\n.own-slack .sl-pill {\n  display: inline-flex; align-items: center; justify-content: center;\n  height: 48px; padding: 0 30px; border-radius: 90px;\n  font-family: var(--f-ui); font-size: 16px; font-weight: 700; line-height: 1;\n  transition: background-color .18s, color .18s, border-color .18s;\n  white-space: nowrap;\n}\n.own-slack .sl-pill-primary { background: var(--primary); color: #fff; }\n.own-slack .sl-pill-primary:hover { background: var(--primary-press); }\n.own-slack .sl-pill-soft { background: var(--canvas-lavender); color: var(--ink); }\n.own-slack .sl-pill-soft:hover { background: #efe0ff; }\n.own-slack .sl-pill-outline { background: #fff; color: var(--primary); border: 2px solid var(--primary); }\n.own-slack .sl-pill-outline:hover { background: var(--canvas-lavender); }\n.own-slack .sl-pill-light { background: #fff; color: var(--primary); }\n.own-slack .sl-pill-light:hover { background: var(--canvas-cream); }\n.own-slack .sl-pill-outline-light { background: transparent; color: #fff; border: 2px solid #fff; }\n.own-slack .sl-pill-outline-light:hover { background: rgba(255,255,255,.12); }\n\n/* ── nav ─────────────────────────────────────────────────────────────── */\n.own-slack .sl-nav {\n  position: sticky; top: 68px; z-index: 40;\n  display: flex; align-items: center; gap: 26px;\n  height: 66px; padding: 0 var(--gut);\n  background: rgba(255,255,255,.9); backdrop-filter: blur(10px);\n  border-bottom: 1px solid var(--hairline);\n}\n.own-slack .sl-brand { display: inline-flex; align-items: center; gap: 9px; font-family: var(--f-display); font-weight: 700; font-size: 21px; letter-spacing: -0.01em; color: var(--primary); }\n.own-slack .sl-brand-mark { width: 16px; height: 16px; border-radius: 5px; background: var(--primary); }\n.own-slack .sl-nav-links { display: flex; align-items: center; gap: 24px; font-size: 16px; font-weight: 400; }\n.own-slack .sl-nav-links a { color: var(--ink); transition: color .18s; }\n.own-slack .sl-nav-links a:hover { color: var(--link-blue); }\n.own-slack .sl-nav-right { margin-left: auto; display: flex; align-items: center; gap: 12px; }\n.own-slack .sl-nav-right .sl-pill { height: 44px; font-size: 16px; padding: 0 22px; }\n\n/* ── hero (pastel mesh) ──────────────────────────────────────────────── */\n.own-slack .sl-hero {\n  position: relative; overflow: hidden;\n  display: grid; grid-template-columns: 1fr 1.05fr; gap: clamp(28px, 4cqi, 64px); align-items: center;\n  padding: clamp(56px, 9cqi, 110px) var(--gut) clamp(56px, 8cqi, 100px);\n}\n.own-slack .sl-hero::before {\n  content: ''; position: absolute; inset: -20% -10%; z-index: -1;\n  background:\n    radial-gradient(42% 50% at 18% 20%, rgba(255, 216, 190, .85), transparent 70%),\n    radial-gradient(46% 54% at 82% 30%, rgba(233, 216, 255, .9), transparent 72%),\n    radial-gradient(50% 60% at 60% 100%, rgba(206, 232, 214, .8), transparent 70%),\n    linear-gradient(180deg, var(--canvas-lavender), var(--canvas-cream));\n}\n.own-slack .sl-hero-copy { max-width: 560px; }\n.own-slack .sl-hero-cta { display: flex; gap: 14px; flex-wrap: wrap; }\n.own-slack .sl-hero-note { margin: 20px 0 0; font-size: 14px; color: var(--ink-mute); }\n\n/* ── product mockup ──────────────────────────────────────────────────── */\n.own-slack .sl-mockup {\n  display: grid; grid-template-columns: 150px 1fr;\n  background: #fff; border-radius: 12px; overflow: hidden;\n  box-shadow: rgba(0,0,0,.1) 0 0 32px 0;\n}\n.own-slack .sl-mk-side { background: var(--primary); padding: 20px 14px; }\n.own-slack .sl-mk-ws { display: block; color: #fff; font-weight: 700; font-size: 14px; margin-bottom: 16px; }\n.own-slack .sl-mk-channels { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }\n.own-slack .sl-mk-channels li { padding: 6px 8px; border-radius: 6px; font-size: 13px; color: var(--on-aubergine-mute); }\n.own-slack .sl-mk-channels li.on { background: rgba(255,255,255,.18); color: #fff; font-weight: 700; }\n.own-slack .sl-mk-main { padding: 18px 20px; display: grid; gap: 14px; background: #fff; }\n.own-slack .sl-mk-head { font-weight: 700; font-size: 15px; color: var(--ink); display: flex; align-items: baseline; gap: 10px; padding-bottom: 12px; border-bottom: 1px solid var(--hairline); }\n.own-slack .sl-mk-sub { font-weight: 400; font-size: 12px; color: var(--ink-mute); }\n.own-slack .sl-msg { display: grid; grid-template-columns: 34px 1fr; gap: 10px; }\n.own-slack .sl-av { width: 34px; height: 34px; border-radius: 6px; display: grid; place-items: center; background: var(--primary); color: #fff; font-size: 12px; font-weight: 700; }\n.own-slack .sl-av-2 { background: var(--link-blue); }\n.own-slack .sl-msg b { font-size: 14px; }\n.own-slack .sl-time { font-size: 12px; color: var(--ink-mute); margin-left: 6px; }\n.own-slack .sl-msg p { margin: 3px 0 0; font-size: 14px; line-height: 1.45; color: var(--ink); }\n.own-slack .sl-chart-card { border: 1px solid var(--hairline); border-left: 3px solid var(--primary); border-radius: 8px; padding: 14px 16px; }\n.own-slack .sl-cc-bars { display: flex; align-items: flex-end; gap: 8px; height: 84px; }\n.own-slack .sl-cc-bars span { flex: 1; height: var(--h); background: var(--primary); border-radius: 3px 3px 0 0; opacity: .85; }\n.own-slack .sl-cc-label { display: block; margin-top: 10px; font-size: 12px; color: var(--ink-mute); }\n\n/* ── logos ───────────────────────────────────────────────────────────── */\n.own-slack .sl-logos { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: clamp(24px, 5cqi, 72px); padding: clamp(40px, 5cqi, 64px) var(--gut); border-top: 1px solid var(--hairline); border-bottom: 1px solid var(--hairline); }\n.own-slack .sl-logos span { font-family: var(--f-display); font-weight: 700; font-size: clamp(16px, 1.7cqi, 22px); letter-spacing: 0.06em; color: #b9b9bb; }\n\n/* ── band ────────────────────────────────────────────────────────────── */\n.own-slack .sl-band { padding: var(--sec) var(--gut) 0; }\n.own-slack .sl-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; margin-top: 44px; }\n.own-slack .sl-card { background: var(--canvas-cream); border-radius: 16px; padding: 32px; }\n.own-slack .sl-card-art { height: 90px; border-radius: 12px; background: #fff; display: grid; place-items: center; margin-bottom: 22px; }\n.own-slack .sl-card-art svg { width: 70%; height: 54px; }\n.own-slack .sl-card h3 { font-family: var(--f-display); font-weight: 700; font-size: 24px; line-height: 1.33; letter-spacing: -0.004em; margin: 0 0 10px; }\n.own-slack .sl-card p { font-size: 16px; line-height: 1.55; color: var(--ink-mute); margin: 0; }\n\n/* ── split / channels ────────────────────────────────────────────────── */\n.own-slack .sl-split { padding: var(--sec) var(--gut) 0; display: grid; grid-template-columns: 1fr 1.1fr; gap: clamp(28px, 4cqi, 64px); align-items: start; }\n.own-slack .sl-split-copy .sl-body { margin-top: 8px; }\n.own-slack .sl-channel-list { display: grid; gap: 10px; }\n.own-slack .sl-channel { display: flex; align-items: center; gap: 16px; padding: 18px 22px; border-radius: 12px; background: var(--canvas-lavender); }\n.own-slack .sl-channel-hash { font-family: var(--f-display); font-weight: 700; font-size: 22px; color: var(--primary); }\n.own-slack .sl-channel-name { font-weight: 700; font-size: 16px; }\n.own-slack .sl-channel-meta { margin-left: auto; font-size: 14px; color: var(--ink-mute); }\n\n/* ── stats ───────────────────────────────────────────────────────────── */\n.own-slack .sl-stats { padding: var(--sec) var(--gut) 0; display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-slack .sl-stat b { display: block; font-family: var(--f-display); font-weight: 700; font-size: clamp(40px, 5.4cqi, 72px); line-height: 1.05; letter-spacing: -0.012em; color: var(--primary); }\n.own-slack .sl-stat span { display: block; margin-top: 10px; font-size: 16px; color: var(--ink-mute); }\n\n/* ── pricing ─────────────────────────────────────────────────────────── */\n.own-slack .sl-tiers { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-top: 44px; }\n.own-slack .sl-tier { background: #fff; border: 1px solid var(--hairline); border-radius: 16px; padding: 32px; display: flex; flex-direction: column; gap: 12px; }\n.own-slack .sl-tier-feat { background: var(--surface-aubergine); color: #fff; border-color: var(--surface-aubergine); }\n.own-slack .sl-tier-name { font-family: var(--f-display); font-weight: 700; font-size: 24px; letter-spacing: -0.004em; }\n.own-slack .sl-tier-price { font-family: var(--f-display); font-weight: 700; font-size: 32px; line-height: 1.25; letter-spacing: -0.008em; }\n.own-slack .sl-tier-price small { font-family: var(--f-ui); font-weight: 400; font-size: 14px; color: var(--ink-mute); }\n.own-slack .sl-tier-feat .sl-tier-price small { color: var(--on-aubergine-mute); }\n.own-slack .sl-tier-list { list-style: none; margin: 6px 0 20px; padding: 0; display: grid; gap: 10px; font-size: 15px; color: var(--ink-mute); }\n.own-slack .sl-tier-feat .sl-tier-list { color: var(--on-aubergine-mute); }\n.own-slack .sl-tier-list li::before { content: '✓'; margin-right: 8px; color: var(--primary); font-weight: 700; }\n.own-slack .sl-tier-feat .sl-tier-list li::before { color: #fff; }\n.own-slack .sl-tier .sl-pill { margin-top: auto; width: 100%; }\n\n/* ── aubergine CTA band ──────────────────────────────────────────────── */\n.own-slack .sl-cta-band {\n  margin-top: var(--sec); padding: clamp(40px, 6cqi, 80px) var(--gut);\n  background: var(--surface-aubergine);\n  display: grid; grid-template-columns: 1.2fr .8fr; gap: 32px; align-items: center;\n}\n.own-slack .sl-cta-actions { display: flex; flex-direction: column; align-items: flex-start; gap: 14px; }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-slack .sl-footer { background: var(--surface-aubergine); color: #fff; padding: clamp(32px, 4cqi, 48px) var(--gut); border-top: 1px solid rgba(255,255,255,.14); }\n.own-slack .sl-foot-grid { display: grid; grid-template-columns: 1.5fr repeat(3, 1fr); gap: 32px; }\n.own-slack .sl-foot-brand .sl-brand { margin-bottom: 14px; }\n.own-slack .sl-foot-col { display: flex; flex-direction: column; gap: 12px; }\n.own-slack .sl-foot-col h3 { margin: 0 0 4px; font-size: 14px; font-weight: 700; color: #fff; }\n.own-slack .sl-foot-col a { color: var(--on-aubergine-mute); font-size: 15px; }\n.own-slack .sl-foot-col a:hover { color: #fff; }\n.own-slack .sl-foot-row { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-top: 36px; padding-top: 22px; border-top: 1px solid rgba(255,255,255,.14); font-size: 14px; color: var(--on-aubergine-mute); }\n\n/* ── reveal on scroll ────────────────────────────────────────────────── */\n.own-slack .sl-rv { opacity: 0; transform: translateY(20px); transition: opacity .55s ease, transform .6s ease; }\n.own-slack .sl-rv.sl-in { opacity: 1; transform: none; }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-slack .sl-hero { grid-template-columns: 1fr; }\n  .own-slack .sl-mockup { order: 2; }\n  .own-slack .sl-grid { grid-template-columns: 1fr 1fr; }\n  .own-slack .sl-split { grid-template-columns: 1fr; }\n  .own-slack .sl-tiers { grid-template-columns: 1fr 1fr; }\n  .own-slack .sl-cta-band { grid-template-columns: 1fr; }\n  .own-slack .sl-foot-grid { grid-template-columns: 1fr 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-slack .sl-nav-links { display: none; }\n  .own-slack .sl-grid { grid-template-columns: 1fr; }\n  .own-slack .sl-stats { grid-template-columns: 1fr; gap: 16px; }\n  .own-slack .sl-mockup { grid-template-columns: 120px 1fr; }\n}\n@container frame (max-width: 430px) {\n  .own-slack .sl-nav-right .sl-pill-soft { display: none; }\n  .own-slack .sl-tiers { grid-template-columns: 1fr; }\n  .own-slack .sl-foot-grid { grid-template-columns: 1fr; }\n  .own-slack .sl-mk-side { display: none; }\n  .own-slack .sl-mockup { grid-template-columns: 1fr; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-slack *, .own-slack *::before, .own-slack *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }\n}\n"};
/* ══ SLACK — own layout behaviour for showcase.html ══════════════════════
   Registers window.OWN_LAYOUTS['slack'].init(root). Renders feature cards,
   the channel list and pricing tiers from data. Returns a cleanup fn. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  var FEATURES = [
    {
      title: 'Shared dashboards',
      body: 'Every region works from the same live boards. No more screenshotting a report into another thread.',
      art: '<svg viewBox="0 0 220 54" fill="none" aria-hidden="true"><rect x="4" y="8" width="64" height="38" rx="6" stroke="#4a154b"/><rect x="78" y="8" width="64" height="38" rx="6" stroke="#4a154b"/><rect x="152" y="8" width="64" height="38" rx="6" fill="#4a154b"/></svg>'
    },
    {
      title: 'Threaded alerts',
      body: 'Route throughput misses into a channel with context attached, so the fix happens where the work happens.',
      art: '<svg viewBox="0 0 220 54" fill="none" aria-hidden="true"><path d="M8 20h60M8 34h120M84 20h60" stroke="#1264a3" stroke-width="3" stroke-linecap="round"/><circle cx="192" cy="20" r="12" fill="#4a154b"/></svg>'
    },
    {
      title: 'Region channels',
      body: 'A channel per site, wired to the right people, metrics and escalation rules the moment it is created.',
      art: '<svg viewBox="0 0 220 54" fill="none" aria-hidden="true"><circle cx="40" cy="27" r="16" stroke="#4a154b"/><circle cx="110" cy="27" r="16" stroke="#4a154b"/><circle cx="180" cy="27" r="16" fill="#4a154b"/><path d="M56 27h38M126 27h38" stroke="#b9b9bb"/></svg>'
    }
  ];

  var CHANNELS = [
    ['throughput', '12 members', 'daily roll-up 09:00'],
    ['region-luzon', '8 members', 'target 4,200/hr'],
    ['region-visayas', '6 members', 'target 2,100/hr'],
    ['alerts', 'auto-routed', 'on-call rotation'],
    ['forecast', '4 members', 'next quarter model']
  ];

  var TIERS = [
    { name: 'Free', price: '$0', unit: '/mo', feats: ['1 region', 'Shared dashboards', 'Community support'], cta: 'Get started', feat: false },
    { name: 'Pro', price: '$8', unit: '/user/mo', feats: ['10 regions', 'Threaded alerts', '90-day history'], cta: 'Get started', feat: false },
    { name: 'Business+', price: '$15', unit: '/user/mo', feats: ['Unlimited regions', 'Forecast model', 'SSO + audit log'], cta: 'Get started', feat: true },
    { name: 'Enterprise', price: "Let's talk", unit: '', feats: ['Dedicated support', 'On-prem option', 'Custom SLAs'], cta: 'Contact sales', feat: false }
  ];

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  OWN['slack'] = {
    init: function (root) {
      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }

      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var disposed = false;
      var observers = [];
      var rafs = [];

      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function $(sel) { return root.querySelector(sel); }

      var grid = $('#slFeatureGrid');
      if (grid) grid.innerHTML = FEATURES.map(function (f) {
        return '<article class="sl-card"><div class="sl-card-art">' + f.art + '</div>'
          + '<h3>' + esc(f.title) + '</h3><p>' + esc(f.body) + '</p></article>';
      }).join('');

      var list = $('#slChannelList');
      if (list) list.innerHTML = CHANNELS.map(function (c) {
        return '<div class="sl-channel"><span class="sl-channel-hash">#</span>'
          + '<span class="sl-channel-name">' + esc(c[0]) + '</span>'
          + '<span class="sl-channel-meta">' + esc(c[1]) + ' · ' + esc(c[2]) + '</span></div>';
      }).join('');

      var tiers = $('#slTierGrid');
      if (tiers) tiers.innerHTML = TIERS.map(function (t) {
        return '<div class="sl-tier' + (t.feat ? ' sl-tier-feat' : '') + '">'
          + '<span class="sl-tier-name">' + esc(t.name) + '</span>'
          + '<span class="sl-tier-price">' + esc(t.price) + (t.unit ? ' <small>' + esc(t.unit) + '</small>' : '') + '</span>'
          + '<ul class="sl-tier-list">' + t.feats.map(function (x) { return '<li>' + esc(x) + '</li>'; }).join('') + '</ul>'
          + '<a class="sl-pill ' + (t.feat ? 'sl-pill-light' : 'sl-pill-primary') + '" href="#">' + esc(t.cta) + '</a>'
          + '</div>';
      }).join('');

      var io = null;
      if (!reduced && typeof IntersectionObserver !== 'undefined') {
        io = new IntersectionObserver(function (ents) {
          ents.forEach(function (en) {
            if (en.isIntersecting) { en.target.classList.add('sl-in'); io.unobserve(en.target); }
          });
        }, { threshold: 0.12 });
        observers.push(io);
        Array.prototype.slice.call(root.querySelectorAll('.sl-card, .sl-tier')).forEach(function (el) {
          el.classList.add('sl-rv'); io.observe(el);
        });
      }

      return function cleanup() {
        disposed = true;
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        rafs.forEach(function (id) { cancelAnimationFrame(id); });
        observers.forEach(function (o) { try { o.disconnect(); } catch (e) { /* ignore */ } });
      };
    }
  };
})();
